"""Deterministic pseudonym generation and text substitution.

Identical real values always receive the identical pseudonym within the
configured scope (``document`` or ``corpus``). Two styles:

* ``token`` — typed counters such as ``PERSON_001``, ``IN_AADHAAR_003``.
* ``faker`` — realistic fakes generated by Faker seeded from an HMAC of
  the real value, so the same input always fakes to the same output
  without the mapping being guessable.
"""

from __future__ import annotations

import logging
import random
import re
from dataclasses import dataclass, field

from presidio_analyzer import RecognizerResult

from .config import PseudonymConfig
from .store import MappingStore

logger = logging.getLogger(__name__)


@dataclass
class PseudonymizationResult:
    text: str
    counts: dict[str, int] = field(default_factory=dict)  # entity_type -> n


def _faker_pseudonym(entity_type: str, seed: int, locale: str) -> str:
    from faker import Faker

    fake = Faker(locale)
    fake.seed_instance(seed)
    generators = {
        "PERSON": fake.name,
        "EMAIL_ADDRESS": fake.email,
        "PHONE_NUMBER": fake.phone_number,
        "LOCATION": fake.city,
        "DATE_TIME": lambda: fake.date_between("-10y", "today").strftime("%d %B %Y"),
        "CREDIT_CARD": fake.credit_card_number,
        "IBAN_CODE": fake.iban,
        "IP_ADDRESS": fake.ipv4,
        "URL": fake.url,
        "ORGANIZATION": fake.company,
        "MONEY_AMOUNT": lambda: f"{random.Random(seed).randint(1, 9_999_999):,}",
    }
    gen = generators.get(entity_type)
    if gen is not None:
        return str(gen())
    # Structured IDs (PAN, Aadhaar, IFSC...) get an unambiguous typed token
    # even in faker mode: emitting a realistic-looking but fake government ID
    # invites confusion, and a token is guaranteed reversible.
    rnd = random.Random(seed)
    return f"{entity_type}_{rnd.randint(0, 999):03d}"


class Pseudonymizer:
    """Applies consistent pseudonyms to analyzer results using the store."""

    def __init__(self, store: MappingStore, cfg: PseudonymConfig) -> None:
        self._store = store
        self._cfg = cfg

    def _scope(self, doc_id: str) -> str:
        return "corpus" if self._cfg.scope == "corpus" else doc_id

    def _new_pseudonym(self, entity_type: str, value: str, scope: str) -> str:
        if self._cfg.style == "faker":
            seed = self._store.hmac_seed(value)
            candidate = _faker_pseudonym(entity_type, seed, self._cfg.faker_locale)
            # Extremely unlikely, but guarantee uniqueness within the scope.
            bump = 0
            while self._store.pseudonym_exists(candidate, scope):
                bump += 1
                candidate = _faker_pseudonym(entity_type, seed + bump,
                                             self._cfg.faker_locale)
            return candidate
        n = self._store.count_for_type(entity_type, scope) + 1
        candidate = f"{entity_type}_{n:03d}"
        while self._store.pseudonym_exists(candidate, scope):
            n += 1
            candidate = f"{entity_type}_{n:03d}"
        return candidate

    def apply(self, text: str, results: list[RecognizerResult],
              doc_id: str) -> PseudonymizationResult:
        """Replace every detected span with its pseudonym (right-to-left so
        earlier offsets stay valid) and persist new mappings."""
        scope = self._scope(doc_id)
        counts: dict[str, int] = {}
        out = text
        for res in sorted(results, key=lambda r: r.start, reverse=True):
            value = text[res.start:res.end]
            stripped = value.strip()
            if not stripped:
                continue
            # Replace only the stripped span so surrounding whitespace
            # (e.g. a newline captured by NER) survives and the reverse
            # operation reproduces the original text exactly.
            start = res.start + (len(value) - len(value.lstrip()))
            end = res.end - (len(value) - len(value.rstrip()))
            pseudonym = self._store.get_pseudonym(stripped, scope)
            if pseudonym is None:
                pseudonym = self._new_pseudonym(res.entity_type, stripped, scope)
                self._store.add_mapping(doc_id, res.entity_type, stripped,
                                        pseudonym, scope)
            out = out[:start] + pseudonym + out[end:]
            counts[res.entity_type] = counts.get(res.entity_type, 0) + 1
        logger.info("Pseudonymized %d spans: %s", sum(counts.values()),
                    ", ".join(f"{k}={v}" for k, v in sorted(counts.items())))
        return PseudonymizationResult(text=out, counts=counts)


def depseudonymize(text: str, store: MappingStore,
                   scope: str | None = None) -> str:
    """Restore real values in LLM output that contains pseudonyms.

    Pseudonyms are replaced longest-first with word-boundary matching so
    ``PERSON_0011`` is never clobbered by ``PERSON_001``.
    """
    mappings = store.all_mappings(scope)
    restored = 0
    for _, pseudonym, real in sorted(mappings, key=lambda m: -len(m[1])):
        pattern = re.compile(re.escape(pseudonym) + r"(?![0-9])")
        text, n = pattern.subn(real.replace("\\", r"\\"), text)
        restored += n
    logger.info("Restored %d pseudonym occurrences", restored)
    return text
